package dev.goforge.containers;

import com.google.gson.*;
import dev.goforge.coverage.GoCoverageProcess;
import java.nio.file.*;
import java.time.Duration;
import java.util.*;

/** Explicit reference-CLI probe; only the generated workspace/image/container are mutated. */
public final class DevContainerProtocolProbe {
    public static void main(String[] args)throws Exception{
        String docker=args[0],context=args[1],node=args[2],cli=args[3],token=args[4];Path root=Path.of(args[5]),report=Path.of(args[6]);
        String image="goforge-devfixture-"+token+":probe",id=null,error=null;var checks=new LinkedHashMap<String,Boolean>();var cleanup=new ArrayList<String>();var env=new HashMap<>(System.getenv());env.put("DOCKER_CONTEXT",context);
        java.util.function.Function<DockerCommands.Request,DockerClient.Result> call=request->{try{var r=DockerClient.execute(docker,context,request,root,env,()->false);if(!r.succeeded())throw new IllegalStateException(r.output());return r;}catch(Exception e){throw new RuntimeException(e);}};
        try{
            Files.writeString(root.resolve("Dockerfile"),"FROM node:24-slim\nLABEL dev.goforge.fixture=\""+token+"\"\n");call.apply(DockerCommands.build(root,root,root.resolve("Dockerfile"),image));checks.put("build_unique_labelled_image_from_existing_local_base",true);
            Path configDir=Files.createDirectory(root.resolve(".devcontainer")),config=configDir.resolve("devcontainer.json");Path hostMarker=root.resolve("host-initialize-must-not-run");
            var original=new JsonObject();original.addProperty("image",image);original.addProperty("initializeCommand","touch '"+hostMarker+"'");original.addProperty("postCreateCommand","printf approved > post-create-marker");Files.writeString(config,"// owned fixture with comments\n"+original.toString());Files.writeString(root.resolve("workspace.txt"),"workspace-"+token);
            var plan=DevContainerPlan.read(root,config,"fixture");Path generated=Files.createDirectory(root.resolve("generated")).resolve("devcontainer.json");var prepared=DevContainerImage.prepare(plan,docker,context,env,()->false);Files.writeString(generated,prepared.configuration());checks.put("plain_image_pinned_after_metadata_preflight",prepared.imageId().matches("sha256:[0-9a-f]{64}")&&JsonParser.parseString(prepared.configuration()).getAsJsonObject().get("image").getAsString().equals(prepared.imageId()));checks.put("host_initialize_and_lifecycle_not_imported",!plan.configuration().contains("initializeCommand")&&!plan.configuration().contains("postCreateCommand"));
            var up=GoCoverageProcess.run(plan.up(node,Path.of(cli),docker,generated),root,env,()->false,Duration.ofMinutes(3));Files.writeString(report.getParent().resolve("devcontainer-up.log"),up.stdout()+"\n"+up.stderr());
            if(!Integer.valueOf(0).equals(up.exitCode())||up.cancelled()||up.timedOut())throw new IllegalStateException("up failed: "+up.stderr());id=JsonParser.parseString(up.stdout()).getAsJsonObject().get("containerId").getAsString();
            var inspect=JsonParser.parseString(call.apply(DockerCommands.inspectContainer(id)).requiredJson()).getAsJsonArray().get(0).getAsJsonObject();checks.put("up_real_owned_container",inspect.getAsJsonObject("Config").getAsJsonObject("Labels").get("dev.goforge.workspace").getAsString().equals(plan.owner()));
            Files.writeString(report.getParent().resolve("container-metadata.json"),new GsonBuilder().setPrettyPrinting().create().toJson(inspect.getAsJsonObject("Config").getAsJsonObject("Labels").get("devcontainer.metadata")));DevContainerImage.verifyContainer(plan,prepared.imageId(),inspect);checks.put("final_container_image_metadata_mounts_permissions_verified",true);
            var reuse=DevContainerImage.prepare(plan,docker,context,env,()->false);checks.put("safe_existing_container_identified_without_cli_reuse",id.equals(reuse.existingContainerId()));
            var alternate=new JsonObject();alternate.addProperty("image","node:24-slim");Files.writeString(config,alternate.toString());try{DevContainerImage.prepare(DevContainerPlan.read(root,config,"fixture"),docker,context,env,()->false);throw new AssertionError("old container with a different image was accepted");}catch(IllegalStateException expected){checks.put("different_image_existing_container_refused",expected.getMessage().contains("different image"));}finally{Files.writeString(config,plan.original());}
            boolean mounted=false;for(var mount:inspect.getAsJsonArray("Mounts")){var m=mount.getAsJsonObject();if(m.has("Source")&&m.get("Source").getAsString().equals(root.toRealPath().toString())&&m.get("Destination").getAsString().equals(plan.workspaceFolder()))mounted=true;}checks.put("exact_current_workspace_bind_mount",mounted);
            var read=call.apply(DockerCommands.exec(id,List.of("cat",plan.workspaceFolder()+"/workspace.txt"),false));checks.put("real_workspace_exec",read.process().stdout().equals("workspace-"+token));checks.put("no_implicit_host_or_postcreate",!Files.exists(hostMarker)&&!Files.exists(root.resolve("post-create-marker")));
            for(var command:DevContainerPlan.commands(plan.lifecycle())){var argv=new ArrayList<>(List.of("container","exec","--workdir",plan.workspaceFolder(),"--",id));argv.addAll(command);call.apply(new DockerCommands.Request("Explicit fixture lifecycle",argv,Duration.ofSeconds(30),true));}
            checks.put("explicit_postcreate_runs_only_when_requested",Files.readString(root.resolve("post-create-marker")).equals("approved")&&!Files.exists(hostMarker));
            call.apply(DockerCommands.lifecycle(DockerCommands.Lifecycle.STOP,id));checks.put("stop",true);var stoppedReuse=DevContainerImage.prepare(plan,docker,context,env,()->false);checks.put("stopped_existing_container_revalidated",id.equals(stoppedReuse.existingContainerId()));call.apply(DockerCommands.lifecycle(DockerCommands.Lifecycle.START,id));call.apply(DockerCommands.lifecycle(DockerCommands.Lifecycle.STOP,id));call.apply(DockerCommands.lifecycle(DockerCommands.Lifecycle.REMOVE,id));id=null;checks.put("remove_owned_container",true);call.apply(DockerCommands.removeImage(image));checks.put("remove_owned_image",true);
            String unsafeImage=image+"-metadata";Files.writeString(root.resolve("Dockerfile"),"FROM node:24-slim\nLABEL dev.goforge.fixture=\""+token+"\"\nLABEL devcontainer.metadata='[{\"privileged\":true,\"mounts\":[\"type=bind,source=/,target=/host\"]}]'\n");call.apply(DockerCommands.build(root,root,root.resolve("Dockerfile"),unsafeImage));
            try{var unsafeJson=new JsonObject();unsafeJson.addProperty("image",unsafeImage);Files.writeString(config,unsafeJson.toString());try{DevContainerImage.prepare(DevContainerPlan.read(root,config,"unsafe"),docker,context,env,()->false);throw new AssertionError("unsafe image accepted");}catch(IllegalArgumentException expected){checks.put("real_image_metadata_rejected_before_up",expected.getMessage().contains("metadata"));}
                Files.writeString(root.resolve("Dockerfile"),"FROM "+unsafeImage+"\n");var buildJson=JsonParser.parseString("{\"build\":{\"context\":\"..\",\"dockerfile\":\"../Dockerfile\"}}");Files.writeString(config,buildJson.toString());try{DevContainerImage.prepare(DevContainerPlan.read(root,config,"unsafe-build"),docker,context,env,()->false);throw new AssertionError("inherited build metadata accepted");}catch(IllegalArgumentException expected){checks.put("real_build_inherited_metadata_rejected_before_up",expected.getMessage().contains("metadata"));}
            }finally{call.apply(DockerCommands.removeImage(unsafeImage));}
            if(checks.values().stream().anyMatch(v->!v))throw new AssertionError(checks);
        }catch(Throwable e){error=e.toString();}
        finally{
            if(id!=null)try{call.apply(DockerCommands.lifecycle(DockerCommands.Lifecycle.STOP,id));call.apply(DockerCommands.lifecycle(DockerCommands.Lifecycle.REMOVE,id));}catch(Exception e){cleanup.add(e.toString());}
            try{var images=DockerData.images(call.apply(DockerCommands.images()).requiredJson());for(var own:images)if(own.repository().equals("goforge-devfixture-"+token))call.apply(DockerCommands.removeImage(DockerCommands.imageReference(own)));}catch(Exception e){cleanup.add(e.toString());}
            var result=new LinkedHashMap<String,Object>();result.put("passed",error==null&&cleanup.isEmpty());result.put("checks",checks);result.put("error",error);result.put("cleanup_errors",cleanup);result.put("native_ui_verified",false);result.put("cli_version","0.89.0");result.put("limitations",List.of("Basic image/build projection; unsupported fields are displayed and not imported","Object postCreate commands execute sequentially after explicit confirmation","Terminal GUI and remote contexts not exercised by this probe","Read-only existing node:24-slim base; unique derived image removed, no global build-cache prune"));Files.writeString(report,new GsonBuilder().setPrettyPrinting().create().toJson(result));
        }
        if(error!=null||!cleanup.isEmpty())throw new AssertionError(error+" "+cleanup);
    }
}
